const test=require('node:test'),assert=require('node:assert/strict');
const load=()=>Promise.all([import('../town-life/economy.mjs'),import('../town-life/civics.mjs')]);
test('30 days: meals, market trade, civic services, school and nonnegative balances',async()=>{const [e]=await load();let s=e.createTown();const population=s.households.reduce((n,h)=>n+h.adults+h.children,0);for(let i=0;i<24*30;i++){s=e.advanceHour(s);for(const h of s.households){assert(h.cash>=0);assert(h.food>=0);assert.equal(h.wellbeing,100);}for(const v of Object.values(s.market))assert(v>=0);assert(s.treasury>=0);}assert.equal(s.meals,population*30);assert(s.transactions>100);assert(s.schoolHours>0);assert(s.businesses.find(b=>b.id==='baker').produced>0);assert(s.imports>0);});
test('closed bakery removes local bread, imports keep households fed',async()=>{const [e]=await load();let s=e.toggleBusiness(e.createTown(),'baker');for(let i=0;i<48;i++)s=e.advanceHour(s);assert.equal(s.businesses.find(b=>b.id==='baker').produced,0);assert(s.meals>0);assert(s.ledger.some(r=>r.kind==='support'));});
test('children go to school and cannot staff workplaces',async()=>{const [e]=await load();const s=e.createTown();s.hour=10;for(const h of s.households)assert.equal(e.routine(s,h,2).place,'school');assert.equal(s.businesses.reduce((n,b)=>n+e.staffing(s,b.id),0),s.households.length*2);});
test('mistaken report closes without custody or criminal label',async()=>{const [e,c]=await load();let s=c.addIncident(e.createTown(),'report');for(let i=0;i<24;i++)s=e.advanceHour(s);assert.equal(s.cases[0].status,'closed');assert(!s.conditions.length);assert(!s.cases[0].history.some(x=>x.includes('ordered time-limited')));assert(!JSON.stringify(s.households).includes('criminal'));});
test('injury removes worker temporarily then recovers and repairs',async()=>{const [e,c]=await load();let s=c.addIncident(e.createTown(),'injury'),id=s.cases[0].person;assert(!c.available(s,id));const initial=e.staffing(e.createTown(),'baker');assert(e.staffing(s,'baker')<initial);for(let i=0;i<24;i++)s=e.advanceHour(s);assert(c.available(s,id));assert.equal(s.cases[0].stage,'recovered');assert.equal(s.maintenanceRepairs,1);});
test('custody requires evidence and review, expires, preserves family',async()=>{const [e,c]=await load();let s=c.addIncident(e.createTown(),'serious');for(let i=0;i<4;i++)s=e.advanceHour(s);assert(!s.conditions.some(x=>x.kind==='custody'));s=e.advanceHour(s);assert.equal(s.cases[0].stage,'custody');assert.equal(s.cases[0].evidence.length,2);for(let i=0;i<24;i++)s=e.advanceHour(s);assert.equal(s.cases[0].status,'closed');assert(!s.conditions.length);assert.equal(s.households.length,12);assert(s.meals>0);});
test('restorative consent can be declined without triggering jail',async()=>{const [e,c]=await load();let s=c.addIncident(e.createTown(),'theft');s.cases[0].consent=false;for(let i=0;i<10;i++)s=e.advanceHour(s);assert.equal(s.cases[0].status,'closed');assert(s.cases[0].history.some(x=>x.includes('not required')));assert(!s.conditions.length);});
